from __future__ import annotations

"""Accumulate scattered observations into a regular grid.

Input is a ``dict`` describing a grid plus a list of observations.  Each
observation carries an ``(x, y)`` position, a ``value`` and a ``quality``.
Observations are binned into cells of the grid and averaged.  The public entry
point :func:`accumulate_grid` validates its input and never raises; it returns a
``dict`` with a boolean ``ok`` field, or a structured response describing the
full accumulated grid.

The public function signature and return contract are stable: callers may rely
on the exact keys and error strings described below.
"""

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    """Validate ``raw`` and accumulate ``observations`` into grid cells.

    Returns either ``{"ok": False, "error": <reason>}`` for malformed input, or
    on success a dict with keys ``ok``, ``cells``, ``flags``, ``dropped``,
    ``rejected``, ``saturated``, ``coverage`` and ``line``.
    """
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}

    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: set[tuple[int, int]] = set()
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        if not _is_valid_observation(obs):
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col = _bounded_index(obs["x"], cell_size, width, tolerance, width * cell_size)
        if col is None:
            dropped = dropped + 1
            continue

        row = _bounded_index(obs["y"], cell_size, height, tolerance, height * cell_size)
        if row is None:
            dropped = dropped + 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded.add(key)

    cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _is_valid_observation(obs: object) -> bool:
    """Return ``True`` when ``obs`` is a well-formed observation dict."""
    if not isinstance(obs, dict):
        return False
    if not isinstance(obs.get("x"), int):
        return False
    if not isinstance(obs.get("y"), int):
        return False
    if not isinstance(obs.get("value"), int):
        return False
    if not isinstance(obs.get("quality"), int):
        return False
    if obs["quality"] < 0 or obs["quality"] > 100:
        return False
    return True


def _bounded_index(coord: int, cell_size: int, dimension: int, tolerance: int, limit: int) -> int | None:
    """Map ``coord`` to a cell index, or return ``None`` when it must be dropped.

    Coordinates in the trailing margin ``[limit, limit + tolerance)`` clamp to
    the final cell; everything beyond that, plus any negative coordinate, is
    considered out of range and dropped (returned as ``None``).
    """
    if coord < 0:
        return None
    index = coord // cell_size
    if index >= dimension:
        if coord - limit < tolerance:
            return dimension - 1
        return None
    return index


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    """Build the ``height`` x ``width`` grid of averaged cell values."""
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: set, width: int, height: int) -> list:
    """Build a per-cell flag grid: ``empty``, ``degraded`` or ``good``."""
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    """Percentage of cells that received at least one observation."""
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    """Compose the human-readable one-line accumulator summary."""
    return (
        f"cells={total_cells};filled={filled};dropped={dropped};"
        f"rejected={rejected};saturated={saturated};coverage={coverage}"
    )

